ALTER TABLE ctf.projection_receipts DROP CONSTRAINT projection_receipts_kind_check;
ALTER TABLE ctf.projection_receipts ADD CONSTRAINT projection_receipts_kind_check CHECK(kind IN ('decision','catalog_mutation','config_mutation','owner_reset','owner_remove','global_reset','ban','unban','blocklist_clear','admit_attempt','record_blocked_attempt','register','start','hint','student_delete','heartbeat'));
CREATE FUNCTION ctf.ctf_heartbeat_receipt_matches(v jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT CASE WHEN ctf.ctf_json_matches(v,'{"type":"object","properties":{"version":{"type":"number","enum":[4]},"kind":{"type":"string","enum":["heartbeat"]},"operationId":{"type":"string","bytes":36,"pattern":"^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$"},"sequence":{"type":"string","bytes":19,"pattern":"^[1-9][0-9]*$","minimum":1,"maximum":"9223372036854775807"},"commandHash":{"type":"string","bytes":64,"pattern":"^[a-f0-9]{64}$"},"outcome":{"type":"string","enum":["applied"]},"data":{"type":"object","properties":{"matched":{"type":"boolean"},"incrementMs":{"type":"number","enum":[0,1000]}}}}}'::jsonb) THEN (v->'data'->>'incrementMs')::integer=CASE WHEN v->'data'->'matched'='true'::jsonb THEN 1000 ELSE 0 END ELSE false END $$;
REVOKE ALL ON FUNCTION ctf.ctf_heartbeat_receipt_matches(jsonb) FROM PUBLIC;
-- Pure closed predicate only; definer execution lets the already-whitelisted
-- validator call this new private helper even when delivery is provisioned later.
CREATE OR REPLACE FUNCTION ctf.valid_projection_result(v text) RETURNS boolean LANGUAGE sql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT CASE WHEN v IS JSON OBJECT WITH UNIQUE KEYS THEN CASE WHEN v::jsonb->>'kind'='heartbeat' THEN ctf.ctf_heartbeat_receipt_matches(v::jsonb) WHEN v::jsonb->>'kind'='student_delete' THEN ctf.ctf_deletion_receipt_matches(v::jsonb) WHEN v::jsonb->>'kind'='decision' THEN ctf.ctf_decision_receipt_matches(v::jsonb) ELSE ctf.ctf_result_matches(v::jsonb) END ELSE false END $$;
REVOKE ALL ON FUNCTION ctf.valid_projection_result(text) FROM PUBLIC;
